parameters.query:
SELECT t.topic_id, t.video_id, t.title, c.config
FROM claim_next_topic($1, $2) t
JOIN channels c ON c.slug = $1;

parameters.jsCode:
const SYSTEM = "You are the head writer of the faceless YouTube channel "{{channel.name}}".

Channel
- Niche: {{channel.niche}}
- Language of the narration: {{channel.language}}
- Tone: {{channel.tone}}
- Point of view (what makes this channel original): {{channel.point_of_view}}

Your job: research the topic on the web, then write the full narration of ONE long video.

Research rules
- Use the web_search tool before writing. Prefer primary or reputable sources (government statistics, professional bodies, established publications).
- Every concrete fact (number, salary, percentage, date, ranking, named requirement) must come from a source you actually found. List each source once in "sources" with the exact claim it supports.
- Never invent numbers. If you cannot verify a figure, describe it qualitatively instead.
- Salaries and statistics change by country: say which country or region a number refers to.

Writing rules
- Total narration: between {{words_min}} and {{words_max}} words. This is read aloud by a synthetic voice at about {{wpm}} words per minute.
- Split the narration into {{blocks_min}} to {{blocks_max}} blocks. Each block is one level or one clear section, 120 to 300 words.
- The first block opens with a hook in the first 10 seconds: a question that only the video answers. No clichés such as "you won't believe".
- Spoken style: short sentences, no lists, no headings inside the narration, no stage directions, no emojis, no URLs.
- Write numbers the way they should be spoken (e.g. "around sixty thousand dollars a year").
- Original point of view in every block: what really changes at this level, the trade-off, the skill that unlocks the next level.
- Avoid generic filler and template phrases. Each block must contain at least one specific, sourced detail.
- End with a short closing that invites a comment about the viewer's own level. No "like and subscribe" begging.

Output
Reply with ONLY one JSON object wrapped in <json> and </json>, with this shape:

<json>
{
  "titles": ["10 YouTube titles, max 60 characters; half start with the search keyword, half curiosity-driven"],
  "chosen_title": "the title you recommend",
  "hook_options": ["5 alternative opening lines, max 30 words each"],
  "sources": [{"id": "src1", "title": "page title", "url": "https://...", "claim": "the exact fact used"}],
  "blocks": [
    {"block_id": "b01", "title": "Level 1 - ...", "narration": "spoken text", "source_ids": ["src1"]}
  ]
}
</json>

block_id values are b01, b02, b03... in order. Use only source ids that exist in "sources".
";
const p = $('Config').first().json;
const t = $input.first().json;
const cfg = typeof t.config === 'string' ? JSON.parse(t.config) : t.config;
const [mmin, mmax] = cfg.format.long_minutes;
const wpm = cfg.format.words_per_minute;
const vars = {
  'channel.name': cfg.name, 'channel.niche': cfg.niche, 'channel.language': cfg.language,
  'channel.tone': cfg.tone, 'channel.point_of_view': cfg.point_of_view || '',
  words_min: Math.round(mmin * wpm), words_max: Math.round(mmax * wpm), wpm,
  blocks_min: 6, blocks_max: 12,
};
const system = SYSTEM.replace(/{{\s*([\w.]+)\s*}}/g, (_, k) => String(vars[k] ?? ''));
const body = {
  model: p.anthropic_model,
  max_tokens: 16000,
  system,
  messages: [{ role: 'user', content: `Topic: ${t.title}

Research it and write the full video now.` }],
  tools: [{ type: 'web_search_20250305', name: 'web_search', max_uses: 6 }],
};
return [{ json: { video_id: t.video_id, topic_id: t.topic_id, title: t.title, config: cfg,
  words_min: vars.words_min, words_max: vars.words_max, body } }];

const resp = $input.first().json;
const ctx = $('Pedido do roteiro').first().json;
const text = (resp.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
const m = text.match(/<json>([\s\S]*)<\/json>/);
if (!m) throw new Error(`Roteiro sem bloco <json> (stop_reason=${resp.stop_reason})`);
let s;
try { s = JSON.parse(m[1]); } catch (e) { throw new Error('JSON do roteiro inválido: ' + e.message); }
if (!Array.isArray(s.blocks) || s.blocks.length < 3) throw new Error('Roteiro com menos de 3 blocos');

const sources = Array.isArray(s.sources) ? s.sources.filter(x => x && x.id && /^https?:\/\//.test(x.url || '')) : [];
const ids = new Set(sources.map(x => x.id));
const clean = t => String(t || '').replace(/\s+/g, ' ').trim();
const blocks = s.blocks.map((b, i) => ({
  block_id: 'b' + String(i + 1).padStart(2, '0'),
  title: clean(b.title) || `Part ${i + 1}`,
  narration: clean(b.narration),
  source_ids: (b.source_ids || []).filter(id => ids.has(id)),
}));
const words = blocks.reduce((n, b) => n + b.narration.split(' ').length, 0);
if (words < ctx.words_min * 0.8) throw new Error(`Roteiro curto demais: ${words} palavras (mínimo ${ctx.words_min})`);

const checks = [
  { stage: 'script', name: 'word_count', passed: words >= ctx.words_min && words <= ctx.words_max * 1.15,
    detail: { words, min: ctx.words_min, max: ctx.words_max } },
  { stage: 'script', name: 'has_sources', passed: sources.length >= 3, detail: { sources: sources.length } },
  { stage: 'script', name: 'blocks_cited', passed: blocks.filter(b => b.source_ids.length).length >= Math.ceil(blocks.length / 2),
    detail: { cited: blocks.filter(b => b.source_ids.length).length, blocks: blocks.length } },
];
const titles = (s.titles || []).map(clean).filter(Boolean).slice(0, 10);
return [{ json: { ...ctx, body: undefined, script: {
  titles: titles.length ? titles : [ctx.title],
  chosen_title: clean(s.chosen_title) || titles[0] || ctx.title,
  hook_options: (s.hook_options || []).map(clean).filter(Boolean),
  sources, blocks }, checks, words } }];

const SYSTEM = "You are the visual director of the faceless YouTube channel "{{channel.name}}".

You receive the finished narration of one video, split into blocks. Turn it into a shot list of about {{shots_total}} shots, in narration order, so that one illustrated image is shown on screen while each piece of narration is read.

Rules for each shot
- "narration_span": the exact words of the narration this shot covers, copied verbatim and contiguous from the block (same spelling and punctuation). Spans of one block, in order, must cover the whole block without gaps or overlaps. A good span is 1 or 2 sentences (about 8 to 14 seconds of speech).
- "visual_prompt": in English, describe subject, action, setting and framing (wide / medium / close-up). Concrete and visual. Do NOT include art style words; the channel style is added automatically.
- Keep characters consistent: refer to the main character the same way every time (e.g. "the young chef, short dark hair, white jacket").
- No real people, no celebrities, no brand logos, no readable text in the image unless it is a short label you also put in "text_overlay".
- "text_overlay": null, or a label of at most 4 words shown on screen (use it on the first shot of each level, e.g. "LEVEL 3", and for key numbers).
- "kenburns": camera movement for this still image, one of push_in, pull_out, pan_left, pan_right, pan_up, pan_down. Vary it; never the same movement more than twice in a row.
- "is_hook": true only for the shots of the first 10 seconds of the video.
- No two shots may have the same visual_prompt.

Distribute shots proportionally to the length of each block.

Output
Reply with ONLY one JSON object wrapped in <json> and </json>:

<json>
{
  "blocks": [
    {"block_id": "b01", "shots": [
      {"narration_span": "...", "visual_prompt": "...", "text_overlay": "LEVEL 1", "kenburns": "push_in", "is_hook": true}
    ]}
  ],
  "thumbnail": {
    "phrases": ["2 lines, max 4 words total, line 2 is the impact word"],
    "image_prompt": "main subject on the right third, left half dark and empty for text, high contrast"
  }
}
</json>
";
const p = $('Config').first().json;
const c = $input.first().json;
const vars = { 'channel.name': c.config.name, shots_total: c.config.format.shots_per_video };
const system = SYSTEM.replace(/{{\s*([\w.]+)\s*}}/g, (_, k) => String(vars[k] ?? ''));
const blocks = c.script.blocks.map(b => ({ block_id: b.block_id, title: b.title, narration: b.narration }));
const body = {
  model: p.anthropic_model,
  max_tokens: 16000,
  system,
  messages: [{ role: 'user', content: 'Narration blocks:
' + JSON.stringify({ blocks }, null, 1) }],
};
return [{ json: { body } }];

const resp = $input.first().json;
const c = $('Validar roteiro').first().json;
const text = (resp.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
const m = text.match(/<json>([\s\S]*)<\/json>/);
if (!m) throw new Error(`Shotlist sem bloco <json> (stop_reason=${resp.stop_reason})`);
const sl = JSON.parse(m[1]);
const norm = t => String(t || '').toLowerCase().replace(/[^a-z0-9à-ÿ]+/g, ' ').trim();
const MOVES = ['push_in', 'pull_out', 'pan_left', 'pan_right', 'pan_up', 'pan_down'];
const byId = Object.fromEntries((sl.blocks || []).map(b => [b.block_id, b]));

let order = 0, found = 0, total = 0, fallbackBlocks = 0;
const blocks = c.script.blocks.map(b => {
  let raw = (byId[b.block_id] || {}).shots || [];
  if (!raw.length) {
    // sem planos para o bloco: 1 plano a cada 2 frases, com o título como cena
    fallbackBlocks++;
    const sentences = b.narration.match(/[^.!?]+[.!?]+/g) || [b.narration];
    raw = [];
    for (let i = 0; i < sentences.length; i += 2) {
      raw.push({ narration_span: sentences.slice(i, i + 2).join(' ').trim(),
        visual_prompt: `${b.title}, illustrative scene, variation ${i / 2 + 1}`, text_overlay: i === 0 ? b.title.split(' - ')[0].slice(0, 30) : null });
    }
  }
  const nb = norm(b.narration);
  const shots = raw.map((s, i) => {
    order++; total++;
    const span = String(s.narration_span || '').trim();
    if (span && nb.includes(norm(span))) found++;
    const kb = MOVES.includes(s.kenburns) ? s.kenburns : MOVES[order % MOVES.length];
    return {
      shot_id: `${b.block_id}-s${String(i + 1).padStart(2, '0')}`,
      order,
      narration_span: span || b.narration.slice(0, 80),
      visual_prompt: (() => { const v = String(s.visual_prompt || '').trim();
        return v.length >= 10 ? v : `${b.title}: ${span || b.narration.slice(0, 120)}`; })(),
      text_overlay: s.text_overlay ? String(s.text_overlay).slice(0, 40) : null,
      // Fase 1: todos os planos com Ken Burns (custo zero). IA de vídeo entra na Fase 2.
      motion: { mode: 'kenburns', kenburns: kb },
      is_hook: Boolean(s.is_hook) && order <= 3,
      image: { url: null, provider: null },
      clip: { url: null, provider: null },
      start_s: null, end_s: null,
    };
  });
  return { ...b, audio: { url: null, duration_s: null, offset_s: null, words: [] }, shots };
});

const spec = {
  video_id: c.video_id,
  channel: c.config.slug,
  topic: c.title,
  language: c.config.language,
  titles: c.script.titles,
  chosen_title: c.script.chosen_title,
  hook_options: c.script.hook_options,
  sources: c.script.sources,
  blocks,
  shorts_candidates: [],
  thumbnail: { phrases: (sl.thumbnail && sl.thumbnail.phrases) || [], image_prompt: (sl.thumbnail && sl.thumbnail.image_prompt) || '', options: [], chosen: null },
  publishing: { description: null, chapters: [], tags: [], pinned_comment: null },
  outputs: { final_url: null, srt_url: null, preview_url: null, duration_s: null },
  checks: [
    ...c.checks,
    { stage: 'shotlist', name: 'shot_count', passed: Math.abs(total - c.config.format.shots_per_video) <= c.config.format.shots_per_video * 0.3,
      detail: { shots: total, target: c.config.format.shots_per_video } },
    { stage: 'shotlist', name: 'spans_match_narration', passed: found >= total * 0.8,
      detail: { found, total, fallback_blocks: fallbackBlocks } },
  ],
};
return [{ json: { video_id: c.video_id, spec, key: `videos/${c.video_id}/video_spec.json` } }];

// O worker chama a URL de retomada do Wait com o resultado do job.
const b = $input.first().json.body;
if (!b) throw new Error('Narração: tempo esgotado esperando o worker');
if (b.status !== 'succeeded') throw new Error('Narração falhou no worker: ' + (b.error || 'sem detalhe'));
return [{ json: b.result }];

// O worker chama a URL de retomada do Wait com o resultado do job.
const b = $input.first().json.body;
if (!b) throw new Error('Imagens: tempo esgotado esperando o worker');
if (b.status !== 'succeeded') throw new Error('Imagens falhou no worker: ' + (b.error || 'sem detalhe'));
return [{ json: b.result }];

// O worker chama a URL de retomada do Wait com o resultado do job.
const b = $input.first().json.body;
if (!b) throw new Error('Montagem: tempo esgotado esperando o worker');
if (b.status !== 'succeeded') throw new Error('Montagem falhou no worker: ' + (b.error || 'sem detalhe'));
return [{ json: b.result }];

const r = $('Checar montagem').first().json;
const [preview, final, srt] = $('Links temporários').first().json.urls;
const spec = r.spec;
const d = Math.round(r.outputs.duration_s);
const dur = `${Math.floor(d / 60)}:${String(d % 60).padStart(2, '0')}`;
const failed = (spec.checks || []).filter(c => !c.passed).map(c => `• ${c.stage}/${c.name}`);
const text = [
  `🎬 *Vídeo pronto para revisão*`,
  `*${spec.chosen_title}*`,
  `Duração: ${dur} · ${spec.blocks.length} blocos · ${spec.sources.length} fontes`,
  failed.length ? `⚠️ Checagens com alerta:\n${failed.join('\n')}` : '✅ Todas as checagens passaram',
  '',
  `▶️ Preview (480p): ${preview}`,
  `⬇️ Vídeo final: ${final}`,
  srt ? `📝 Legenda SRT: ${srt}` : '',
  '',
  'Links válidos por 48 h. Fase 1: publique pelo YouTube Studio.',
].filter(x => x !== '').join('\n');
return [{ json: { number: $('Pegar próximo tema').first().json.config.approval.to, text } }];
